    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass UnionFind:\n    def __init__(self, n):\n        self.f = list(range(n))\n\n    def find(self, x):\n        if self.f[x] != x:\n            self.f[x] = self.find(self.f[x])\n        return self.f[x]\n\n    def unite(self, x, y):\n        x = self.find(x)\n        y = self.find(y)\n        if x == y:\n            return\n        # \u603b\u662f\u8ba9\u5b57\u5178\u5e8f\u66f4\u5c0f\u7684\u4f5c\u4e3a\u96c6\u5408\u4ee3\u8868\u5b57\u7b26\n        if x > y:\n            x, y = y, x\n        self.f[y] = x\n\nclass Solution:\n    def smallestEquivalentString(self, s1: str, s2: str, baseStr: str) -> str:\n        uf = UnionFind(26)\n        for a, b in zip(s1, s2):\n            uf.unite(ord(a) - ord('a'), ord(b) - ord('a'))\n        return ''.join(chr(ord('a') + uf.find(ord(c) - ord('a'))) for c in baseStr)\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.smallestEquivalentString(_args[0], _args[1], _args[2])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
