    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def findLexSmallestString(self, s: str, a: int, b: int) -> str:\n        n = len(s)\n        vis = [False] * n\n        res = s\n        # \u5c06 s \u5ef6\u957f\u4e00\u500d\uff0c\u65b9\u4fbf\u622a\u53d6\u8f6e\u8f6c\u540e\u7684\u5b57\u7b26\u4e32 t\n        s = s + s\n        i = 0\n        while not vis[i]:\n            vis[i] = True\n            for j in range(10):\n                k_limit = 0 if b % 2 == 0 else 9\n                for k in range(k_limit + 1):\n                    # \u6bcf\u6b21\u8fdb\u884c\u7d2f\u52a0\u4e4b\u524d\uff0c\u91cd\u65b0\u622a\u53d6 t\n                    t = list(s[i:i + n])\n                    for p in range(1, n, 2):\n                        t[p] = str((int(t[p]) + j * a) % 10)\n                    for p in range(0, n, 2):\n                        t[p] = str((int(t[p]) + k * a) % 10)\n                    t_str = ''.join(t)\n                    if t_str < res:\n                        res = t_str\n            i = (i + b) % n\n        return res\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.findLexSmallestString(_args[0], _args[1], _args[2])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
