    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def countSubIslands(self, grid1: List[List[int]], grid2: List[List[int]]) -> int:\n        m, n = len(grid1), len(grid1[0])\n\n        def bfs(sx: int, sy: int) -> int:\n            q = deque([(sx, sy)])\n            grid2[sx][sy] = 0\n            # \u5224\u65ad\u5c9b\u5c7f\u5305\u542b\u7684\u6bcf\u4e00\u4e2a\u683c\u5b50\u662f\u5426\u90fd\u5728 grid1 \u4e2d\u51fa\u73b0\u4e86\n            check = (grid1[sx][sy] == 1)\n            while q:\n                x, y = q.popleft()\n                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):\n                    if 0 <= nx < m and 0 <= ny < n and grid2[nx][ny] == 1:\n                        q.append((nx, ny))\n                        grid2[nx][ny] = 0\n                        if grid1[nx][ny] != 1:\n                            check = False\n            \n            return int(check)\n\n        ans = 0\n        for i in range(m):\n            for j in range(n):\n                if grid2[i][j] == 1:\n                    ans += bfs(i, j)\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.countSubIslands(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
